// Go: regexp is RE2-based, linear time
package main

import (
	"fmt"
	"regexp"
	"strings"
)

func main() {
	evil := regexp.MustCompile(`^(\w+\s?)*$`) // exponential in backtracking engines
	s := strings.Repeat("a", 50000) + "!"
	fmt.Println(evil.MatchString(s)) // false, returns in milliseconds

	_, err := regexp.Compile(`(\w)\1`)
	fmt.Println(err) // error parsing regexp: invalid escape sequence: `\1`

	re := regexp.MustCompile(`(?P<k>\w+)=(?P<v>\d+)`)
	fmt.Println(re.FindStringSubmatch("x=42")) // [x=42 x 42]
}
